-- ============================================================== 3. privileges for the application account
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'lims_app') THEN CREATE ROLE lims_app NOLOGIN; END IF;
END $$;
GRANT USAGE ON SCHEMA lims TO lims_app;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA lims TO lims_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA lims TO lims_app;
REVOKE DELETE, TRUNCATE ON ALL TABLES IN SCHEMA lims FROM lims_app;
REVOKE UPDATE ON audit_log FROM lims_app;
REVOKE UPDATE ON signature_event FROM lims_app;
REVOKE UPDATE ON auth_event FROM lims_app;
REVOKE UPDATE ON document_file FROM lims_app;
REVOKE UPDATE ON inventory_transaction FROM lims_app;
REVOKE UPDATE ON sensor_reading FROM lims_app;
